import { readFile, writeFile } from 'node:fs/promises';

// Keeps tasks in memory and, if you give it a file, saves after every change.
export function createStore(file) {
  let tasks = [];
  let nextId = 1;

  const ready = file
    ? readFile(file, 'utf8')
        .then((text) => {
          tasks = JSON.parse(text);
          nextId = tasks.reduce((max, t) => Math.max(max, t.id), 0) + 1;
        })
        .catch((err) => {
          if (err.code !== 'ENOENT') throw err;   // no file yet is fine, anything else is not
        })
    : Promise.resolve();

  const save = () => (file ? writeFile(file, JSON.stringify(tasks, null, 2)) : Promise.resolve());

  return {
    async list() { await ready; return tasks; },
    async get(id) { await ready; return tasks.find((t) => t.id === id); },
    async create(data) {
      await ready;
      const task = { id: nextId++, title: data.title, done: false, createdAt: new Date().toISOString() };
      tasks.push(task);
      await save();
      return task;
    },
    async update(id, data) {
      await ready;
      const task = tasks.find((t) => t.id === id);
      if (!task) return undefined;
      Object.assign(task, data);
      await save();
      return task;
    },
    async remove(id) {
      await ready;
      const before = tasks.length;
      tasks = tasks.filter((t) => t.id !== id);
      if (tasks.length === before) return false;
      await save();
      return true;
    },
  };
}

import express from 'express';
import { createStore } from './store.js';
import { checkTask } from './validate.js';

const port = Number(process.env.PORT) || 3000;
const store = createStore(process.env.DATA_FILE || './data/tasks.json');

const app = express();
app.use(express.json());

app.get('/api/tasks', async (req, res) => {
  res.json(await store.list());
});

app.post('/api/tasks', async (req, res) => {
  const { value, error } = checkTask(req.body);
  if (error) return res.status(400).json({ error });
  res.status(201).json(await store.create(value));
});

app.patch('/api/tasks/:id', async (req, res) => {
  const { value, error } = checkTask(req.body, { partial: true });
  if (error) return res.status(400).json({ error });
  const task = await store.update(Number(req.params.id), value);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.json(task);
});

app.delete('/api/tasks/:id', async (req, res) => {
  const removed = await store.remove(Number(req.params.id));
  if (!removed) return res.status(404).json({ error: 'Task not found' });
  res.status(204).end();
});

app.listen(port, () => console.log(`Server running on port ${port}`));

