  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.status(204).end();
});

import { Router } from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

export function authRouter({ secret, users }) {
  const router = Router();
  const sign = (user) => jwt.sign({ sub: user.id, email: user.email }, secret, { expiresIn: '1h' });
  const emailOk = (e) => typeof e === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

  router.post('/register', async (req, res) => {
    const { email, password } = req.body ?? {};
    if (!emailOk(email)) return res.status(400).json({ error: 'Enter a valid email' });
    if (typeof password !== 'string' || password.length < 8) {
      return res.status(400).json({ error: 'Password must be at least 8 characters' });
    }
    const key = email.toLowerCase();
    if (users.has(key)) return res.status(409).json({ error: 'That email is already registered' });
    const user = { id: users.size + 1, email: key, passwordHash: await bcrypt.hash(password, 10) };
    users.set(key, user);
    res.status(201).json({ token: sign(user) });
  });

  router.post('/login', async (req, res) => {
    const { email, password } = req.body ?? {};
    const user = typeof email === 'string' ? users.get(email.toLowerCase()) : undefined;
    const ok = user && typeof password === 'string' && (await bcrypt.compare(password, user.passwordHash));
    if (!ok) return res.status(401).json({ error: 'Wrong email or password' });
    res.json({ token: sign(user) });
  });

  return router;
}

import jwt from 'jsonwebtoken';

export function requireAuth(secret) {
  return (req, res, next) => {
    const header = req.get('Authorization') || '';
    const [scheme, token] = header.split(' ');
    if (scheme !== 'Bearer' || !token) return res.status(401).json({ error: 'Log in first' });
    try {
      const payload = jwt.verify(token, secret);
      req.user = { id: payload.sub, email: payload.email };
      next();
    } catch {
      res.status(401).json({ error: 'Token is invalid or expired' });
    }
  };
}

import { readFile, writeFile } from 'node:fs/promises';

// A tiny store that keeps everything in memory and, if you give it a file, saves after each change.
export function createStore(file) {
  let tasks = [];
  let nextId = 1;
  let ready = Promise.resolve();

  if (file) {
    ready = readFile(file, 'utf8')
      .then((text) => {
        tasks = JSON.parse(text);
        nextId = tasks.reduce((max, t) => Math.max(max, t.id), 0) + 1;
      })
      .catch((err) => {
        if (err.code !== 'ENOENT') throw err;      // no file yet is fine, anything else is not
      });
  }

  const save = () => (file ? writeFile(file, JSON.stringify(tasks, null, 2)) : Promise.resolve());

  return {
    async list(ownerId) { await ready; return tasks.filter((t) => t.ownerId === ownerId); },
    async get(ownerId, id) { await ready; return tasks.find((t) => t.id === id && t.ownerId === ownerId); },
    async create(ownerId, data) {
      await ready;
      const task = { id: nextId++, ownerId, title: data.title, done: false, createdAt: new Date().toISOString() };
      tasks.push(task);
      await save();
      return task;
    },
    async update(ownerId, id, data) {
      await ready;
      const task = tasks.find((t) => t.id === id && t.ownerId === ownerId);
      if (!task) return undefined;
      Object.assign(task, data);
      await save();
      return task;
    },
    async remove(ownerId, id) {
      await ready;
      const before = tasks.length;
      tasks = tasks.filter((t) => !(t.id === id && t.ownerId === ownerId));
      if (tasks.length === before) return false;
      await save();
      return true;
    },
  };
}

import { Router } from 'express';
import { checkTask } from '../validate.js';

export function tasksRouter(store) {
  const router = Router();

  router.get('/', async (req, res) => {
    const list = await store.list(req.user.id);
    const { done } = req.query;
    if (done === 'true') return res.json(list.filter((t) => t.done));
    if (done === 'false') return res.json(list.filter((t) => !t.done));
    res.json(list);
  });

  router.get('/:id', async (req, res) => {
    const task = await store.get(req.user.id, Number(req.params.id));
    if (!task) return res.status(404).json({ error: 'Task not found' });
    res.json(task);
  });

  router.post('/', async (req, res) => {
    const { value, error } = checkTask(req.body);
    if (error) return res.status(400).json({ error });
    const task = await store.create(req.user.id, value);
    res.status(201).location(`/api/tasks/${task.id}`).json(task);
  });

  router.patch('/:id', async (req, res) => {
    const { value, error } = checkTask(req.body, { partial: true });
    if (error) return res.status(400).json({ error });
    const task = await store.update(req.user.id, Number(req.params.id), value);
    if (!task) return res.status(404).json({ error: 'Task not found' });
    res.json(task);
  });

  router.delete('/:id', async (req, res) => {
    const removed = await store.remove(req.user.id, Number(req.params.id));
    if (!removed) return res.status(404).json({ error: 'Task not found' });
    res.status(204).end();
  });

  return router;
}

