  assert.equal((await request(app).post('/api/files').set(as(3)).attach('file', two, { filename: '3.txt', contentType: 'text/plain' })).status, 413);

  assert.equal((await request(app).delete(`/api/files/${up.body.id}`).set(as(1))).status, 204);
  assert.equal(fs.readdirSync(folder).length, 2);
  fs.rmSync(folder, { recursive: true });
});

// Project 9: SaaS subscriptions. Plans, subscribe, limits per plan, and billing events from a provider webhook.
import express from 'express';
import crypto from 'node:crypto';
import { AppError, requireAuth, errorHandler, notFoundHandler } from './p-kit.js';

export const PLANS = {
  free: { priceCents: 0, projects: 1 },
  pro: { priceCents: 49900, projects: 10 },
  team: { priceCents: 199900, projects: 100 },
};

export const sign = (raw, secret) => crypto.createHmac('sha256', secret).update(raw).digest('hex');

export function createApp({ billing, webhookSecret, now = () => Date.now() }) {
  const app = express();
  const auth = requireAuth();
  const accounts = new Map();       // userId -> { plan, status, renewsAt }
  const projects = new Map();       // userId -> [names]
  const seen = new Set();

  const accountOf = (id) => accounts.get(id) ?? accounts.set(id, { plan: 'free', status: 'active', renewsAt: null }).get(id);

  // The webhook uses the raw body so the signature can be checked.
  app.post('/webhooks/billing', express.raw({ type: 'application/json' }), (req, res) => {
    const given = req.get('x-signature') ?? '';
    const expected = sign(req.body, webhookSecret);
    if (given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected))) return res.status(400).json({ error: 'Bad signature' });
    const event = JSON.parse(req.body.toString('utf8'));
    if (seen.has(event.id)) return res.json({ duplicate: true });
    seen.add(event.id);

    const account = accountOf(event.userId);
    if (event.type === 'subscription.paid') Object.assign(account, { plan: event.plan, status: 'active', renewsAt: now() + 30 * 86_400_000 });
    if (event.type === 'subscription.payment_failed') account.status = 'past_due';
    if (event.type === 'subscription.cancelled') Object.assign(account, { plan: 'free', status: 'active', renewsAt: null });
    res.json({ received: true });
  });

  app.use(express.json());

  app.get('/api/plans', (req, res) => res.json(PLANS));

  // We do NOT activate the plan here. We start a checkout; the paid webhook activates it.
  app.post('/api/subscribe', auth, async (req, res) => {
    const plan = req.body?.plan;
    if (!PLANS[plan] || plan === 'free') throw new AppError('Choose pro or team', 422);
    const checkout = await billing.createCheckout({ userId: req.user.id, plan, amountCents: PLANS[plan].priceCents });
    res.status(201).json({ checkoutUrl: checkout.url });
  });

  app.get('/api/account', auth, (req, res) => res.json({ ...accountOf(req.user.id), limits: PLANS[accountOf(req.user.id).plan], used: (projects.get(req.user.id) ?? []).length }));

  // Entitlement check: what the plan allows is decided on the server, on every request.
  app.post('/api/projects', auth, (req, res) => {
    const account = accountOf(req.user.id);
    if (account.status === 'past_due') throw new AppError('Your last payment failed. Update your payment method.', 402);
    const list = projects.get(req.user.id) ?? [];
    if (list.length >= PLANS[account.plan].projects) throw new AppError(`Your ${account.plan} plan allows ${PLANS[account.plan].projects} project(s). Upgrade to add more.`, 403);
    projects.set(req.user.id, [...list, String(req.body?.name ?? 'Untitled')]);
    res.status(201).json({ count: list.length + 1 });
  });

  app.use(notFoundHandler, errorHandler);
  return app;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import { createApp, sign } from './p09-saas.js';
import { signToken } from './p-kit.js';

const SECRET = 'whsec_saas';
const as = (id) => ({ Authorization: `Bearer ${signToken({ id, role: 'user', name: `u${id}` })}` });
const hook = (app, event) => {
  const raw = JSON.stringify(event);
  return request(app).post('/webhooks/billing').set('Content-Type', 'application/json').set('x-signature', sign(raw, SECRET)).send(raw);
};

test('project 9: limits follow the plan and the webhook', async () => {
  const app = createApp({ billing: { createCheckout: async ({ plan }) => ({ url: `https://pay.example/${plan}` }) }, webhookSecret: SECRET });

  assert.equal((await request(app).post('/api/projects').set(as(1)).send({ name: 'A' })).status, 201);
  assert.equal((await request(app).post('/api/projects').set(as(1)).send({ name: 'B' })).status, 403);       // free plan: 1 project

  assert.equal((await request(app).post('/api/subscribe').set(as(1)).send({ plan: 'free' })).status, 422);
  const checkout = await request(app).post('/api/subscribe').set(as(1)).send({ plan: 'pro' });
  assert.equal(checkout.body.checkoutUrl, 'https://pay.example/pro');
  assert.equal((await request(app).get('/api/account').set(as(1))).body.plan, 'free');                       // not active until paid

  assert.equal((await request(app).post('/webhooks/billing').set('Content-Type', 'application/json').set('x-signature', 'bad').send('{}')).status, 400);
  await hook(app, { id: 'e1', type: 'subscription.paid', userId: 1, plan: 'pro' });
  assert.equal((await request(app).get('/api/account').set(as(1))).body.plan, 'pro');
  assert.equal((await request(app).post('/api/projects').set(as(1)).send({ name: 'B' })).status, 201);

  assert.equal((await hook(app, { id: 'e1', type: 'subscription.paid', userId: 1, plan: 'team' })).body.duplicate, true);   // same event again
  assert.equal((await request(app).get('/api/account').set(as(1))).body.plan, 'pro');

  await hook(app, { id: 'e2', type: 'subscription.payment_failed', userId: 1 });
  assert.equal((await request(app).post('/api/projects').set(as(1)).send({ name: 'C' })).status, 402);

  await hook(app, { id: 'e3', type: 'subscription.cancelled', userId: 1 });
  assert.equal((await request(app).get('/api/account').set(as(1))).body.plan, 'free');
});

// Project 10: three small services and a gateway, running in one process so you can test them.
//   users service      owns user data
//   orders service     owns orders, asks the users service who the customer is, publishes "order.created"
//   notifications      listens to events from the broker (a queue between services)
//   gateway            the ONLY public door: checks the token, then forwards to a service
import express from 'express';
import http from 'node:http';
import { EventEmitter } from 'node:events';
import { requireAuth, errorHandler, notFoundHandler, AppError } from './p-kit.js';

const listen = (app) => new Promise((resolve) => { const server = http.createServer(app).listen(0, () => resolve({ server, url: `http://127.0.0.1:${server.address().port}` })); });

// A message broker in miniature. In production this is Redis (BullMQ), RabbitMQ or Kafka.
export function createBroker() {
  const bus = new EventEmitter();
  return { publish: (topic, message) => setImmediate(() => bus.emit(topic, message)), subscribe: (topic, handler) => bus.on(topic, handler) };
}

export async function startUsers() {
  const app = express();
  const users = new Map([[1, { id: 1, name: 'Asha' }], [2, { id: 2, name: 'Ravi' }]]);
  app.get('/users/:id', (req, res) => (users.has(Number(req.params.id)) ? res.json(users.get(Number(req.params.id))) : res.status(404).json({ error: 'User not found' })));
  app.get('/health', (req, res) => res.json({ ok: true }));
  return listen(app);
}

export async function startOrders({ usersUrl, broker }) {
  const app = express();
  app.use(express.json());
  const orders = [];

  app.post('/orders', async (req, res) => {
    // Service-to-service call with a time limit: never wait forever for another service.
    let customer;
    try {
      const reply = await fetch(`${usersUrl}/users/${req.body.userId}`, { signal: AbortSignal.timeout(1000) });
      if (reply.status === 404) return res.status(422).json({ error: 'Unknown user' });
      customer = await reply.json();
    } catch {
      return res.status(503).json({ error: 'User service is not available, try again later' });   // fail clearly, do not crash
    }
    const order = { id: orders.length + 1, userId: customer.id, item: String(req.body.item ?? ''), status: 'created' };
    orders.push(order);
    broker.publish('order.created', { orderId: order.id, userName: customer.name, item: order.item });    // others react later
    res.status(201).json(order);
  });

  app.get('/orders', (req, res) => res.json(orders.filter((o) => o.userId === Number(req.query.userId))));
  app.get('/health', (req, res) => res.json({ ok: true }));
  return listen(app);
}

export function startNotifications({ broker }) {
  const sent = [];
  broker.subscribe('order.created', (event) => sent.push(`Thanks ${event.userName}, we got your order for ${event.item}`));
  return { sent };
}

export async function startGateway({ usersUrl, ordersUrl }) {
  const app = express();
  app.use(express.json());
  const auth = requireAuth();

  const forward = (base) => async (req, res) => {
    const reply = await fetch(base + req.originalUrl.replace(/^\/api/, ''), {
      method: req.method,
      headers: { 'content-type': 'application/json' },
      body: ['GET', 'HEAD'].includes(req.method) ? undefined : JSON.stringify({ ...req.body, userId: req.user.id }),   // the user id comes from the TOKEN, never from the client
      signal: AbortSignal.timeout(2000),
    });
    res.status(reply.status).json(await reply.json());
  };

  app.get('/api/users/me', auth, (req, res, next) => { req.url = `/users/${req.user.id}`; req.originalUrl = req.url; next(); }, forward(usersUrl));
  app.post('/api/orders', auth, forward(ordersUrl));
  app.get('/api/orders', auth, (req, res, next) => { req.originalUrl = `/orders?userId=${req.user.id}`; next(); }, forward(ordersUrl));
  app.get('/health', (req, res) => res.json({ ok: true }));

  app.use(notFoundHandler);
  app.use((err, req, res, next) => (err.name === 'TimeoutError' ? res.status(504).json({ error: 'Service timed out' }) : errorHandler(err, req, res, next)));
  return { ...(await listen(app)), app };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import { createBroker, startUsers, startOrders, startNotifications, startGateway } from './p10-microservices.js';
import { signToken } from './p-kit.js';

const as = (id) => ({ Authorization: `Bearer ${signToken({ id, role: 'user', name: `u${id}` })}` });

test('project 10: gateway, services and events', async () => {
  const broker = createBroker();
  const users = await startUsers();
  const orders = await startOrders({ usersUrl: users.url, broker });
  const notifications = startNotifications({ broker });
  const gateway = await startGateway({ usersUrl: users.url, ordersUrl: orders.url });

  assert.equal((await request(gateway.url).get('/api/orders')).status, 401);              // the gateway checks the token

  const me = await request(gateway.url).get('/api/users/me').set(as(1));
  assert.equal(me.body.name, 'Asha');

  // The client tries to order as another user: the gateway overwrites userId from the token.
  const order = await request(gateway.url).post('/api/orders').set(as(1)).send({ item: 'Keyboard', userId: 2 });
  assert.equal(order.status, 201);
  assert.equal(order.body.userId, 1);

  await new Promise((resolve) => setTimeout(resolve, 20));
  assert.deepEqual(notifications.sent, ['Thanks Asha, we got your order for Keyboard']);   // another service reacted to the event

  assert.equal((await request(gateway.url).get('/api/orders').set(as(1))).body.length, 1);
  assert.equal((await request(gateway.url).get('/api/orders').set(as(2))).body.length, 0);
  assert.equal((await request(gateway.url).post('/api/orders').set(as(99)).send({ item: 'X' })).status, 422);    // unknown user

  // Take the users service down: orders fail clearly with 503 instead of hanging or crashing.
  users.server.close();
  users.server.closeAllConnections();
  assert.equal((await request(gateway.url).post('/api/orders').set(as(1)).send({ item: 'Mouse' })).status, 503);

  for (const s of [orders, gateway]) { s.server.close(); s.server.closeAllConnections(); }
});
